PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','member','viewer')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE login_attempts (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE companies (id TEXT PRIMARY KEY, name TEXT NOT NULL, website TEXT, parent_id TEXT REFERENCES companies(id), customer_type TEXT CHECK(customer_type IN ('venue_management','group_single_business','group_diversified_business')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE contacts (id TEXT PRIMARY KEY, company_id TEXT REFERENCES companies(id), name TEXT NOT NULL, role TEXT, email TEXT, phone TEXT, source_url TEXT);
CREATE TABLE regions (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, presence_level INTEGER CHECK(presence_level BETWEEN 1 AND 3), support_model TEXT, owner_id TEXT REFERENCES users(id));
INSERT INTO regions(id,name,presence_level,support_model) VALUES('australia','Australia',1,'Established operations');
CREATE TABLE venues (id TEXT PRIMARY KEY, name TEXT NOT NULL, company_id TEXT REFERENCES companies(id), country TEXT NOT NULL, city TEXT, address TEXT, physical_stage TEXT NOT NULL, confidence TEXT NOT NULL, latitude REAL, longitude REAL, payload TEXT NOT NULL CHECK(json_valid(payload)), revision INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX venues_search ON venues(country,physical_stage,confidence);
CREATE TABLE venue_identity_keys (key TEXT PRIMARY KEY, venue_id TEXT NOT NULL REFERENCES venues(id));
CREATE TABLE exhibitions (id TEXT PRIMARY KEY, identity_key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, country TEXT NOT NULL, city TEXT, venue TEXT, start_date TEXT NOT NULL, end_date TEXT NOT NULL CHECK(end_date >= start_date), confidence TEXT NOT NULL DEFAULT 'unverified', payload TEXT NOT NULL CHECK(json_valid(payload)), revision INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX exhibition_dates ON exhibitions(start_date,end_date,country);
CREATE TABLE sources (id TEXT PRIMARY KEY, url TEXT NOT NULL UNIQUE, publisher TEXT, payload TEXT NOT NULL CHECK(json_valid(payload)), discovered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE source_collections (collection TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), PRIMARY KEY(collection,source_id));
CREATE TABLE exhibition_sources (exhibition_id TEXT NOT NULL REFERENCES exhibitions(id), source_id TEXT NOT NULL REFERENCES sources(id), PRIMARY KEY(exhibition_id,source_id));
CREATE TABLE venue_sources (venue_id TEXT NOT NULL REFERENCES venues(id), source_id TEXT NOT NULL REFERENCES sources(id), PRIMARY KEY(venue_id,source_id));
CREATE TABLE dataset_metadata (key TEXT PRIMARY KEY, payload TEXT NOT NULL CHECK(json_valid(payload)), imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE record_notes (entity_type TEXT NOT NULL CHECK(entity_type IN ('exhibition','venue')), entity_id TEXT NOT NULL, text TEXT NOT NULL DEFAULT '', review TEXT NOT NULL DEFAULT 'new', revision INTEGER NOT NULL DEFAULT 1, updated_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(entity_type,entity_id));
CREATE TABLE exclusions (id TEXT PRIMARY KEY REFERENCES venues(id), snapshot TEXT NOT NULL, removed_by TEXT NOT NULL REFERENCES users(id), removed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE exclusion_keys (key TEXT PRIMARY KEY, exclusion_id TEXT NOT NULL REFERENCES exclusions(id));
CREATE TABLE work_projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, workstream TEXT NOT NULL CHECK(workstream IN ('readiness','brand_awareness','market_access','partnerships','target_customers')), work_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','on_hold','completed','cancelled')), owner_id TEXT REFERENCES users(id), country TEXT, due_date TEXT, next_action TEXT, deliverable TEXT, outcome TEXT, exhibition_level INTEGER CHECK(exhibition_level BETWEEN 1 AND 3), exhibition_id TEXT UNIQUE REFERENCES exhibitions(id), company_id TEXT REFERENCES companies(id), latitude REAL, longitude REAL, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX projects_filters ON work_projects(workstream,country,status,owner_id);
CREATE TABLE tasks (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES work_projects(id), title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','blocked','done','cancelled')), owner_id TEXT REFERENCES users(id), due_date TEXT, deliverable TEXT, needs_decision INTEGER NOT NULL DEFAULT 0 CHECK(needs_decision IN (0,1)), revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE partners (company_id TEXT NOT NULL REFERENCES companies(id), type TEXT NOT NULL CHECK(type IN ('equipment_manufacturer','channel_partner','technology_partner','delivery_service_partner')), status TEXT NOT NULL DEFAULT 'prospective' CHECK(status IN ('prospective','active','paused')), PRIMARY KEY(company_id,type));
CREATE TABLE opportunities (id TEXT PRIMARY KEY, company_id TEXT REFERENCES companies(id), venue_id TEXT REFERENCES venues(id), name TEXT NOT NULL, owner_id TEXT REFERENCES users(id), disposition TEXT NOT NULL DEFAULT 'active' CHECK(disposition IN ('active','on_hold','closed_lost','disqualified')), next_action TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE milestone_confirmations (id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(id), milestone TEXT NOT NULL CHECK(milestone IN ('V1','V2','V3')), evidence TEXT NOT NULL, confirmed_by TEXT NOT NULL REFERENCES users(id), confirmed_at TEXT NOT NULL, revoked_at TEXT);
CREATE UNIQUE INDEX active_milestones ON milestone_confirmations(opportunity_id,milestone) WHERE revoked_at IS NULL;
CREATE TABLE quote_references (id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(id), source_system TEXT NOT NULL, external_id TEXT NOT NULL, url TEXT, version TEXT, UNIQUE(source_system,external_id,version));
CREATE TABLE orders (id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(id), company_id TEXT NOT NULL REFERENCES companies(id), quote_reference_id TEXT REFERENCES quote_references(id), approved_scope TEXT, agreement_file_id TEXT, signed_at TEXT);
CREATE TABLE payments (id TEXT PRIMARY KEY, order_id TEXT REFERENCES orders(id), opportunity_id TEXT NOT NULL REFERENCES opportunities(id), amount_minor INTEGER NOT NULL, currency TEXT NOT NULL, nature TEXT NOT NULL, verified_by TEXT NOT NULL REFERENCES users(id), received_at TEXT NOT NULL, reference TEXT NOT NULL);
CREATE TABLE handovers (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), pack TEXT NOT NULL CHECK(pack IN ('software','hardware')), recipient TEXT NOT NULL, scope TEXT NOT NULL, accepted_at TEXT, UNIQUE(order_id,pack));
CREATE TABLE files (id TEXT PRIMARY KEY, object_key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, content_type TEXT NOT NULL, bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, owner_id TEXT REFERENCES users(id), project_id TEXT REFERENCES work_projects(id), category TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE activity (id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, user_id TEXT REFERENCES users(id), detail TEXT NOT NULL CHECK(json_valid(detail)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX activity_entity ON activity(entity_type,entity_id,created_at);
